INSERT INTO `about_us_pages` VALUES (1,'about_us',NULL,'About Us','693ae83073a1e1765468208.png',NULL,NULL,NULL,NULL,'Innovative solutions <br /> to boost your projects',NULL,NULL,NULL,'<p class=\"about-us-text\">Vestibulum ante ipsum primis in faucibus orci luctus et ultrices posuere consectetur sed, convallis at tellus. Donec rutrum congue leo eget malesuada. Curabitur arcu erat, accumsan id imperdiet et, porttitor at sem. Vestibulum ac diam sit amet quam vehicula elementum sed sit amet </p>\r\n                        <p class=\"about-us-text\">Praesent sapien massa, convallis a pellentesque nec, egestas non nisi. Vivamus suscipit tortor eget felis porttitor volutpat. Sed porttitor lectus nibh. Nulla porttitor accumsan tincidunt. Pellentesque in ipsum id orci porta dapibus. Praesent sapien massa, convallis a pellentesque nec, </p>',NULL,NULL,NULL,'ديس ابتكار الحلول <br/> صب الداعم لك المشاريع',NULL,NULL,NULL,'معلومات عنا','<p class=\"about-us-text\">عند مدخل مدخل العفاريت ، كان الألم والانتقام يكمن في الوادي الرئيسي ولكن الوادي عند الأرض. حتى يحتاج الأسد إلى التوحيد. لقد كان قوسًا ، وطبقة من هذا التمويل ، وعبارة في سيم. الدهليوم&nbsp;</p><p class=\"about-us-text\">كتلة الحاضر حكيمة وليست من وادي القناص ، لكنها ليست من العوز. يعيش لرفع الجلاد يحتاج عطلة نهاية الأسبوع عبارة غاز. لكن العبارة اختارت الكرة. لا توجد طبقة مبتكرة لإيقافها. باسم هذا شركة مصفاة نفط عمان إنها كتلة من الحكماء</p>',NULL,NULL,NULL,'2024-03-24 20:23:47','2025-12-11 13:50:08'),(2,'comfort',NULL,NULL,'693ae83cbea671765468220.png',NULL,NULL,NULL,NULL,'All Day Comfort',NULL,NULL,NULL,'<span data-metadata=\"<!--(figmeta)eyJmaWxlS2V5IjoiT0ZwbEFXNUd1d0ZCV1gxUG04UWthSCIsInBhc3RlSUQiOjc2MDM4NDYzMywiZGF0YVR5cGUiOiJzY2VuZSJ9Cg==(/figmeta)-->\"></span><span data-buffer=\"<!--(figma)(/figma)-->\"></span><span style=\"white-space-collapse: preserve;\"><b>شركة مطاحن الشرع</b>&nbsp;تعمل كموقع للبيع بالتجزئة بالإضافة إلى عملها كسوق للبائعين من جهات خارجية. وتقدم&nbsp;شركة مطاحن الشرع&nbsp;تجربة تسوق مريحة وآمنة مع إمكانية الدفع عبر الإنترنت، وإمكانية الدفع نقداً عند استلام السلع، وإمكانية إرجاعها مجاناً.</span>',NULL,NULL,NULL,'راحة طوال اليوم',NULL,NULL,NULL,NULL,'نعتقد أن ارتداء الملابس يجب أن يكون أسهل جزء من يومك.',NULL,NULL,NULL,'2024-03-24 20:23:47','2025-12-11 13:50:20'),(3,'features','Our Features','Why Choose Us',NULL,'features-icon-1.png','features-icon-2.png','features-icon-3.png',NULL,'Why Choose Us','Men\'s Collection','Innovative Solutions',NULL,'We believe getting dressed should be the easiest part of your day.','We believe getting dressed should be the easiest part of your day.','We believe getting dressed should be the easiest part of your day.',NULL,'لماذا أخترتنا','مجموعة الرجال','حلول مبتكرة',NULL,NULL,'نعتقد أن ارتداء الملابس يجب أن يكون أسهل جزء من يومك.','نعتقد أن ارتداء الملابس يجب أن يكون أسهل جزء من يومك.','نعتقد أن ارتداء الملابس يجب أن يكون أسهل جزء من يومك.',NULL,'2024-03-24 20:23:47','2024-03-24 20:23:47');
