--
-- Table structure for table `orders`
--

DROP TABLE IF EXISTS `orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `orders` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `Order_Number` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `User_Id` bigint unsigned DEFAULT NULL,
  `Billing_Id` bigint unsigned DEFAULT NULL,
  `Shipping_Id` bigint unsigned DEFAULT NULL,
  `billing_address` text COLLATE utf8mb4_unicode_ci,
  `shipping_address` text COLLATE utf8mb4_unicode_ci,
  `Coupon_Id` bigint unsigned DEFAULT NULL,
  `Coupon_Amount` decimal(12,3) NOT NULL DEFAULT '0.000',
  `Delivery_Charge` decimal(12,3) NOT NULL DEFAULT '0.000',
  `Sub_Total` decimal(12,3) NOT NULL DEFAULT '0.000',
  `Tax` decimal(12,3) NOT NULL DEFAULT '0.000',
  `Grand_Total` decimal(12,3) NOT NULL DEFAULT '0.000',
  `wallet_used` decimal(10,3) NOT NULL DEFAULT '0.000',
  `Is_Free_Delivery` tinyint NOT NULL DEFAULT '0',
  `Is_Order_Successful` tinyint NOT NULL DEFAULT '0',
  `Is_Order_Completed` tinyint NOT NULL DEFAULT '0',
  `Payment_Method` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '5',
  `Payment_Status` tinyint NOT NULL DEFAULT '5',
  `is_paid` tinyint(1) NOT NULL DEFAULT '0',
  `pending_token` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `payment_session_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `smartlife_invoice_id` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `smartlife_synced_at` timestamp NULL DEFAULT NULL,
  `Order_Status` tinyint NOT NULL DEFAULT '1',
  `txn` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `order_source` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `Delivery_At` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `delivery_man_id` bigint unsigned DEFAULT NULL,
  `delivery_status` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `admin_id` bigint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `orders_pending_token_unique` (`pending_token`),
  KEY `orders_user_id_foreign` (`User_Id`),
  KEY `orders_billing_id_foreign` (`Billing_Id`),
  KEY `orders_shipping_id_foreign` (`Shipping_Id`),
  KEY `orders_coupon_id_foreign` (`Coupon_Id`),
  KEY `orders_admin_id_foreign` (`admin_id`),
  KEY `orders_created_at_idx` (`created_at`),
  KEY `orders_delivery_at_idx` (`Delivery_At`),
  KEY `orders_order_status_idx` (`Order_Status`),
  KEY `orders_created_at_index` (`created_at`),
  KEY `orders_delivery_at_index` (`Delivery_At`),
  KEY `orders_order_status_index` (`Order_Status`),
  KEY `orders_payment_session_id_index` (`payment_session_id`),
  KEY `orders_smartlife_invoice_id_index` (`smartlife_invoice_id`),
  KEY `orders_delivery_man_id_foreign` (`delivery_man_id`),
  CONSTRAINT `orders_admin_id_foreign` FOREIGN KEY (`admin_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `orders_billing_id_foreign` FOREIGN KEY (`Billing_Id`) REFERENCES `billings` (`id`) ON DELETE CASCADE,
  CONSTRAINT `orders_coupon_id_foreign` FOREIGN KEY (`Coupon_Id`) REFERENCES `coupons` (`id`) ON DELETE CASCADE,
  CONSTRAINT `orders_delivery_man_id_foreign` FOREIGN KEY (`delivery_man_id`) REFERENCES `delivery_men` (`id`) ON DELETE SET NULL,
  CONSTRAINT `orders_shipping_id_foreign` FOREIGN KEY (`Shipping_Id`) REFERENCES `shippings` (`id`) ON DELETE CASCADE,
  CONSTRAINT `orders_user_id_foreign` FOREIGN KEY (`User_Id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=42 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

